mapper.select:

where p.del_flag = '0' and s.del_flag = '0'

    AND p.school_id = #{schoolId}


    AND s.country = #{country}


    AND p.degree = #{degree}


    AND p.field_group = #{fieldGroup}


    AND p.major_direction = #{majorDirection}


    AND p.difficulty = #{difficulty}


    AND p.status = #{status}


    AND (p.program_name like concat('%', #{programName}, '%') or p.program_name_en ilike concat('%', #{programName}, '%'))


    AND (p.verified_time is null or p.verified_time < now() - interval '90 days')

order by s.country, s.school_name_en, p.program_name_en

